#!ibl edition=2
$s = [limbs:browser]{op:"snapshot"}
$card = ($s.snapshot >> [table:filter]{where:($e)=>contains($e.name,"W-1004")})[0]
$dc = [limbs:browser]{op:"click", ref:$card.ref, mode:"double"}
$s2 = [limbs:browser]{op:"snapshot"}
$inp = $s2.snapshot >> [table:filter]{where:($e)=>$e.role=="textbox"}
$ty = [limbs:browser]{op:"type", ref:$inp[0].ref, text:"탐침 메모"}
$en = [limbs:browser]{op:"press_key", key:"Enter"}
$w = [limbs:browser]{op:"wait", text:"메모: 탐침 메모"}
$s3 = [limbs:browser]{op:"snapshot"}
$card3 = ($s3.snapshot >> [table:filter]{where:($e)=>contains($e.name,"W-1004")})
$rc = [limbs:browser]{op:"click", ref:$card3[0].ref, mode:"right"}
$s4 = [limbs:browser]{op:"snapshot"}
$menu = $s4.snapshot >> [table:filter]{where:($e)=>$e.role=="menuitem" or $e.role=="menu"}
$mk = [limbs:browser]{op:"click", ref:($menu >> [table:filter]{where:($e)=>contains($e.name,"우선")})[0].ref}
$t = [limbs:browser]{op:"evaluate", expression:"document.querySelector('.card[data-id=\"W-1004\"]').innerText + ' | ctx=' + !!document.getElementById('ctx')"}
return {dbl:$dc, inp:$inp, typed:$ty, enter:$en, wait:$w, card3:$card3, right:$rc, menu:$menu, menuclick:$mk, card_text:$t.result}
